{"variables":{},"query":"{
  categories: clipart_categories(
    where: {type: {_eq: "clipart"}, deleted_at: {_is_null: true}, parent_id: {_is_null: true}}
    order_by: {created_at: desc}
    limit: 25
  ) {
    id
    type
    parent_id
    label: name
    __typename
  }
}"}

{"operationName":"getData","variables":{"limit":20},"query":"query getData($limit: Int!) {
  layer_images_connection(
    first: $limit
    where: {deleted_at: {_is_null: true}, _and: [{master: {_nilike: "%.svg"}}, {master: {_nilike: "%.gpx"}}]}
    order_by: {id: desc}
  ) {
    edges {
      cursor
      node {
        id
        master
        url
        thumbnail
        name
        width
        height
        created_at
        layer_image_category_id
        __typename
      }
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
      __typename
    }
    __typename
  }
}"}
